"""Allfolds-first fixed origin identification; current formal v12 comparison."""
from research_r4_common import ROOT,now,dump,sha,evidence
from research_r70_member_origin import predict_calibrated
import json,numpy as np,sys
from scipy.special import expit,logit
def main(stage):
 plan=json.loads((ROOT/'research_r74_plan.json').read_text());out=ROOT/f'research_artifacts/r74_member_origins_{stage}';base=np.load(ROOT/f'research_artifacts/r68_pure_ranknet_{stage}/oof.npz');v11=np.load(ROOT/f'research_artifacts/r23_conditional_lean_{stage}/oof.npz');assert all(np.array_equal(base[n],v11[n]) for n in ['id','target','fold']);pred=np.full(len(base['id']),np.nan)
 for k in sorted(np.unique(base['fold'])):
  run=out/f'fold{k}';r=json.loads((run/'result.json').read_text());assert r['status']=='complete' and r['plan_sha256']==sha(ROOT/'research_r74_plan.json') and r['runner_sha256']==plan['source_sha256']['research_r74_worker.py'] and r['new_classifier_fits']==0 and all(sha(run/n)==h for n,h in r['files_sha256'].items());z=np.load(run/'validation.npz');idx=np.load(run/'indices.npz');vi=np.flatnonzero(base['fold']==k);fi=np.flatnonzero(base['fold']!=k);assert np.array_equal(idx['fi'],fi) and np.array_equal(idx['vi'],vi) and np.array_equal(idx['train_id'],base['id'][fi]) and np.array_equal(idx['valid_id'],base['id'][vi]);assert all(np.array_equal(z[n],v) for n,v in [('idx',vi),('id',base['id'][vi]),('target',base['target'][vi])]);bias=np.asarray(json.loads((run/'origins.json').read_text())['bias']);margin=np.load(run/'validation_margins.npy',mmap_mode='r');assert np.array_equal(predict_calibrated(margin,bias),z['pred']);pred[vi]=z['pred']
 candidate=expit(.875*logit(np.clip(v11['candidate'],1e-6,1-1e-6))+.125*logit(np.clip(pred,1e-6,1-1e-6)));assert np.isfinite(candidate).all();np.savez_compressed(out/'oof.npz',id=base['id'],target=base['target'],fold=base['fold'],pred=pred,candidate=candidate,reference_v12=base['candidate'],reference_v11=v11['candidate']);proof=evidence(base['target'],base['candidate'],candidate,base['fold']);record=dict(status='complete',stage=stage,checked_utc=now(),eligible=proof['eligible_for_new_partition_replication'],vs_formal_v12=proof,all_folds_before_scoring=True,new_classifier_fits=0,oof_sha256=sha(out/'oof.npz'),plan_sha256=sha(ROOT/'research_r74_plan.json'));dump(out/'result.json',record);print(json.dumps(record,indent=2),flush=True)
if __name__=='__main__':main(sys.argv[1])
